import React, { useMemo } from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, spring } from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadInter = makeLoadFont('Inter');

const { fontFamily: interFamily } = loadInter();



export type PhoneTranscriptionProps = Record<string, any>;

const SpeakerRow: React.FC<{
  speaker: string;
  isActive: boolean;
  phoneW: number;
  accentColor: string;
  frame: number;
}> = ({ speaker, isActive, phoneW, accentColor, frame }) => {
  const avatarColor = isActive ? accentColor : '#f2f2f7';
  const textColor = isActive ? '#fff' : '#8e8e93';
  const nameColor = isActive ? '#000' : '#8e8e93';
  const fontWeight = isActive ? 700 : 500;

  return (
    <div style={{
      display: 'flex',
      alignItems: 'center',
      padding: phoneW * 0.04,
      backgroundColor: isActive ? '#fff' : '#fafafa',
      borderRadius: phoneW * 0.04,
      boxShadow: isActive ? '0 10px 30px rgba(0,0,0,0.08)' : 'none',
      border: `2px solid ${isActive ? accentColor : 'transparent'}`,
      gap: phoneW * 0.04,
      transition: 'none'
    }}>
      <div style={{
        width: phoneW * 0.12,
        height: phoneW * 0.12,
        borderRadius: '50%',
        backgroundColor: avatarColor,
        display: 'flex',
        justifyContent: 'center',
        alignItems: 'center',
        color: textColor,
        fontSize: phoneW * 0.05,
        fontWeight: 700,
        position: 'relative'
      }}>
        {speaker.charAt(0).toUpperCase()}
      </div>
      
      <div style={{ flex: 1, fontSize: phoneW * 0.045, color: nameColor, fontWeight }}>
        {speaker}
      </div>

      <div style={{ display: 'flex', gap: phoneW * 0.01, alignItems: 'center', height: phoneW * 0.08, width: phoneW * 0.12, justifyContent: 'center' }}>
        {[0, 1, 2, 3].map(i => {
          const amplitude = isActive ? interpolate(Math.sin((frame + i * 5) / 4), [-1, 1], [20, 100]) : 10;
          return (
            <div key={i} style={{
              width: phoneW * 0.012,
              height: `${amplitude}%`,
              backgroundColor: isActive ? accentColor : '#d1d1d6',
              borderRadius: phoneW * 0.01,
              transition: 'none'
            }} />
          );
        })}
      </div>
    </div>
  );
};

const PhoneTranscription: React.FC<PhoneTranscriptionProps> = ({
  backgroundColor = "#f2f2f7",
  transparentBackground = false,
  durationInSeconds = 15,
  callTitle = "Call with Francesco",
  timeLabel = "9:41 AM 17:32",
  accentColor = "#d8ad3b",
  speakingTurns = [
    { speaker: "Francesco", durationInSeconds: 5 },
    { speaker: "You", durationInSeconds: 4 },
    { speaker: "Francesco", durationInSeconds: 6 }
  ],
}) => {
  const frame = useCurrentFrame();
  const { fps, height } = useVideoConfig();

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  const phoneH = height * 0.85;
  const phoneW = phoneH / 2.16; 

  const START_DELAY = fps * 0.5; 
  const activeFrame = Math.max(0, frame - START_DELAY);
  
  const uniqueSpeakers = useMemo(() => {
    return Array.from(new Set(speakingTurns.map(t => t.speaker)));
  }, [speakingTurns]);

  let currentSpeaker: string | null = null;
  let accumulatedFrames = 0;
  for (const turn of speakingTurns) {
    const turnFrames = turn.durationInSeconds * fps;
    if (activeFrame >= accumulatedFrames && activeFrame < accumulatedFrames + turnFrames) {
      currentSpeaker = turn.speaker;
      break;
    }
    accumulatedFrames += turnFrames;
  }

  const phoneScale = spring({ frame, fps, config: { damping: 14, mass: 0.8 }, from: 0.9, to: 1 });
  const phoneOpacity = interpolate(frame, [0, 15], [0, 1], { extrapolateRight: 'clamp' });

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, fontFamily: interFamily, display: 'flex', justifyContent: 'center', alignItems: 'center' }}>
      
      <div style={{
        width: phoneW,
        height: phoneH,
        backgroundColor: '#111',
        borderRadius: phoneW * 0.12,
        border: `${phoneW * 0.015}px solid #333`,
        boxShadow: '0 30px 60px rgba(0,0,0,0.15), inset 0 0 0 2px #000',
        position: 'relative',
        overflow: 'hidden',
        display: 'flex',
        flexDirection: 'column',
        transform: `scale(${phoneScale})`,
        opacity: phoneOpacity,
      }}>
        
        <div style={{
          width: phoneW * 0.3,
          height: phoneH * 0.035,
          backgroundColor: '#000',
          borderRadius: phoneH * 0.02,
          position: 'absolute',
          top: phoneH * 0.015,
          left: '50%',
          transform: 'translateX(-50%)',
          zIndex: 20
        }} />

        <div style={{ position: 'absolute', top: 0, left: 0, right: 0, height: phoneH * 0.06, display: 'flex', justifyContent: 'space-between', padding: `0 ${phoneW * 0.08}px`, color: '#000', fontSize: phoneW * 0.035, fontWeight: 600, alignItems: 'center', zIndex: 10, boxSizing: 'border-box' }}>
          <span>9:41</span>
          <div style={{ display: 'flex', gap: 5 }}>
            <svg width="16" height="16" viewBox="0 0 24 24" fill="#000"><path d="M12 21L15.6 16.2C14.6 15.4 13.4 15 12 15C10.6 15 9.4 15.4 8.4 16.2L12 21ZM12 3C7 3 2.7 5.8 0 10L12 21L24 10C21.3 5.8 17 3 12 3Z" fillOpacity="0.3"/><path d="M12 21L24 10C23.5 9.4 22.9 8.8 22.2 8.3L12 21ZM12 21L0 10C0.5 9.4 1.1 8.8 1.8 8.3L12 21Z"/></svg>
            <svg width="18" height="18" viewBox="0 0 24 24" fill="none"><rect x="2" y="7" width="16" height="10" rx="2" ry="2" stroke="#000" strokeWidth="2"/><path d="M22 11V13" stroke="#000" strokeWidth="2" strokeLinecap="round"/><rect x="4" y="9" width="12" height="6" rx="1" fill="#000"/></svg>
          </div>
        </div>

        <div style={{ position: 'absolute', top: 0, left: 0, right: 0, bottom: 0, backgroundColor: '#000', zIndex: 0 }} />

        <div style={{
          flex: 1,
          backgroundColor: '#fff',
          padding: `${phoneW * 0.08}px`,
          paddingTop: `${phoneH * 0.09}px`,
          display: 'flex',
          flexDirection: 'column',
          position: 'relative',
          zIndex: 5,
          marginTop: 0
        }}>

          <div style={{ textAlign: 'center', marginBottom: phoneW * 0.06 }}>
            <div style={{ fontWeight: 700, fontSize: phoneW * 0.055, color: '#000', letterSpacing: '-0.02em' }}>{callTitle}</div>
            <div style={{ color: '#8e8e93', fontSize: phoneW * 0.035, marginTop: phoneW * 0.01, fontWeight: 500 }}>{timeLabel}</div>
          </div>

          <div style={{ flex: 1, display: 'flex', flexDirection: 'column', justifyContent: 'center', gap: phoneW * 0.05, paddingBottom: phoneW * 0.15 }}>
            {uniqueSpeakers.map((speaker, idx) => {
              const isActive = currentSpeaker === speaker;
              return (
                <SpeakerRow 
                  key={idx}
                  speaker={speaker}
                  isActive={isActive}
                  phoneW={phoneW}
                  accentColor={accentColor}
                  frame={activeFrame}
                />
              );
            })}
          </div>

          <div style={{ position: 'absolute', bottom: phoneW * 0.05, left: phoneW * 0.05, width: phoneW * 0.08, height: phoneW * 0.08, backgroundColor: accentColor, borderRadius: phoneW * 0.02, display: 'flex', justifyContent: 'center', alignItems: 'center' }}>
             <svg width={phoneW * 0.05} height={phoneW * 0.05} viewBox="0 0 24 24" fill="white"><path d="M20 2H4c-1.1 0-2 .9-2 2v18l4-4h14c1.1 0 2-.9 2-2V4c0-1.1-.9-2-2-2zm-2 9H6V9h12v2zm0-3H6V6h12v2z"/></svg>
          </div>
          <div style={{ position: 'absolute', bottom: phoneW * 0.07, right: phoneW * 0.05, color: accentColor, fontWeight: 600, fontSize: phoneW * 0.04 }}>
            Done
          </div>

        </div>
      </div>
    </AbsoluteFill>
  );
};

export default PhoneTranscription;